// Test AWS credentials by making a simple STS call
async function testAWSCredentials() {
    console.log('🔄 Testing AWS credentials...');

    if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
        console.log('❌ AWS credentials not found');
        return false;
    }

    try {
        // Use AWS CLI to test credentials
        const result = await new Promise((resolve, reject) => {
            const aws = spawn('aws', [
                'sts', 'get-caller-identity',
                '--region', 'us-east-1'
            ], {
                env: {
                    ...process.env,
                    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
                    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
                    AWS_DEFAULT_REGION: 'us-east-1'
                }
            });

            let stdout = '';
            let stderr = '';

            aws.stdout.on('data', (data) => {
                stdout += data.toString();
            });

            aws.stderr.on('data', (data) => {
                stderr += data.toString();
            });

            aws.on('close', (code) => {
                if (code === 0) {
                    try {
                        const identity = JSON.parse(stdout);
                        resolve({ valid: true, identity });
                    } catch (e) {
                        resolve({ valid: false, error: 'Invalid JSON response' });
                    }
                } else {
                    resolve({ valid: false, error: stderr || `Exit code: ${code}` });
                }
            });
        });

        if (result.valid) {
            console.log(`✅ AWS credentials valid - User: ${result.identity.UserId}, Account: ${result.identity.Account}`);
            return true;
        } else {
            console.log(`❌ AWS credentials invalid: ${result.error}`);
            return false;
        }
    } catch (error) {
        console.log(`❌ AWS test failed: ${error.message}`);
        return false;
    }
}

