            ], {
                env: {
                    PGPASSWORD: connectionConfig.password
                }
            });

            let stderr = '';
            ping.stderr.on('data', (data) => {
                stderr += data.toString();
            });

            ping.on('close', (code) => {
                resolve({ success: code === 0, error: stderr });
            });
        });

        if (result.success) {
