async function testDatabaseConnection(url) {
    console.log('🧪 Testing Database Connection...');

    // Parse PostgreSQL URL
    const match = url.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
    if (!match) {
        console.log('❌ Invalid PostgreSQL URL format');
        return false;
