function makeHttpRequest(options, body = null) {
    return new Promise((resolve, reject) => {
        const req = https.request(options, (res) => {
            let data = '';
            res.on('data', (chunk) => data += chunk);
            res.on('end', () => resolve({ 
                statusCode: res.statusCode, 
                headers: res.headers, 
                data 
            }));
        });

        req.on('error', reject);
        req.setTimeout(5000, () => {
            req.destroy();
