#!/usr/bin/env node

// Credential Validation Script
// Tests connectivity and validity of credentials from .env.test

const https = require('https');
const { exec } = require('child_process');
const fs = require('fs');

// Parse .env.test file
function parseEnvFile(filePath) {
  const envContent = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    if (line.trim() && !line.startsWith('#')) {
      const [key, value] = line.split('=').map(part => part.trim());
      if (key && value) {
        envVars[key] = value;
      }
    }
  });

  return envVars;
}

// Test Database Connectivity
async function testDatabaseConnection(dbUrl) {
  return new Promise((resolve) => {
    console.log(`\n🔍 Testing Database: ${dbUrl.replace(/:[^:]*@/, ':****@')}`);

    // Extract components from PostgreSQL URL
    const match = dbUrl.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
    if (!match) {
      console.log('❌ Invalid PostgreSQL URL format');
      resolve({ valid: false, error: 'Invalid URL format' });
      return;
    }

    const [, user, password, host, port, database] = match;

    // Try to connect using psql if available
    exec(`which psql`, (error) => {
      if (error) {
        console.log('ℹ️  psql not available, testing network connectivity only');

        // Test network connectivity to the host:port
        const net = require('net');
        const socket = new net.Socket();

        socket.setTimeout(5000);

        socket.on('connect', () => {
          console.log('✅ Network connectivity to database host: OK');
          socket.destroy();
          resolve({ valid: true, type: 'network_only' });
        });

        socket.on('timeout', () => {
          console.log('❌ Database host connection timeout');
          socket.destroy();
          resolve({ valid: false, error: 'Connection timeout' });
        });

        socket.on('error', (err) => {
          console.log(`❌ Database host connection error: ${err.message}`);
          resolve({ valid: false, error: err.message });
        });

        socket.connect(parseInt(port), host);

      } else {
        // Test with psql
        const cmd = `PGPASSWORD="${password}" psql -h ${host} -p ${port} -U ${user} -d ${database} -c "SELECT 1" -t`;

        exec(cmd, { timeout: 10000 }, (error, stdout, stderr) => {
          if (error) {
            console.log(`❌ Database connection failed: ${error.message}`);
            if (stderr) console.log(`   Error details: ${stderr.trim()}`);
            resolve({ valid: false, error: error.message });
          } else {
            console.log('✅ Database connection: OK');
            resolve({ valid: true, type: 'full_connection' });
          }
        });
      }
    });
  });
}

// Test AWS Credentials
async function testAWSCredentials(accessKeyId, secretAccessKey) {
  return new Promise((resolve) => {
    console.log(`\n🔍 Testing AWS Credentials: ${accessKeyId.substring(0, 8)}...`);

    // AWS credential format validation
    const awsAccessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    const awsSecretPattern = /^[A-Za-z0-9+/]{40}$/;

    if (!awsAccessKeyPattern.test(accessKeyId)) {
      console.log('❌ Invalid AWS Access Key ID format');
      resolve({ valid: false, error: 'Invalid format' });
      return;
    }

    if (!awsSecretPattern.test(secretAccessKey)) {
      console.log('❌ Invalid AWS Secret Access Key format');
      resolve({ valid: false, error: 'Invalid format' });
      return;
    }

    console.log('✅ AWS credential format: VALID');

    // Try to list S3 buckets (will fail with invalid credentials but show what error)
    exec(`AWS_ACCESS_KEY_ID=${accessKeyId} AWS_SECRET_ACCESS_KEY=${secretAccessKey} aws sts get-caller-identity --output json 2>&1 || true`, 
      { timeout: 10000 }, (error, stdout, stderr) => {
        const output = stdout || stderr;

        if (output.includes('InvalidClientTokenId') || output.includes('SignatureDoesNotMatch')) {
          console.log('❌ AWS credentials: INVALID (authentication failed)');
          resolve({ valid: false, error: 'Authentication failed' });
        } else if (output.includes('AccessDenied')) {
          console.log('✅ AWS credentials: VALID but permissions limited');
          resolve({ valid: true, type: 'limited_permissions' });
        } else if (output.includes('Arn') || output.includes('UserId')) {
          console.log('✅ AWS credentials: VALID with permissions');
          resolve({ valid: true, type: 'full_access' });
        } else {
          console.log('⚠️  AWS credentials: UNCERTAIN (check AWS CLI installation)');
          console.log(`   Response: ${output.substring(0, 200)}...`);
          resolve({ valid: null, error: 'Unable to determine validity' });
        }
      });
  });
}

// Test API Key Format Validation
function testAPIKeyFormat(keyName, keyValue, expectedPattern) {
  console.log(`\n🔍 Testing ${keyName}: ${keyValue.substring(0, 8)}...`);

  if (expectedPattern.test(keyValue)) {
    console.log(`✅ ${keyName} format: VALID`);
    return { valid: true, type: 'format_valid' };
  } else {
    console.log(`❌ ${keyName} format: INVALID`);
    return { valid: false, error: 'Invalid format' };
  }
}

// Test HTTP API endpoints
async function testAPIEndpoint(url, headers = {}, method = 'GET') {
  return new Promise((resolve) => {
    console.log(`\n🔍 Testing API endpoint: ${method} ${url}`);

    const parsedUrl = new URL(url);
    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
      path: parsedUrl.pathname + parsedUrl.search,
      method: method,
      headers: headers,
      timeout: 10000
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✅ API endpoint: RESPONDED (HTTP ${res.statusCode})`);
          resolve({ valid: true, status: res.statusCode });
        } else if (res.statusCode === 401 || res.statusCode === 403) {
          console.log(`❌ API endpoint: AUTHENTICATION FAILED (HTTP ${res.statusCode})`);
          resolve({ valid: false, error: `HTTP ${res.statusCode}` });
        } else {
          console.log(`⚠️  API endpoint: UNEXPECTED RESPONSE (HTTP ${res.statusCode})`);
          resolve({ valid: null, status: res.statusCode });
        }
      });
    });

    req.on('timeout', () => {
      console.log('❌ API endpoint: TIMEOUT');
      req.destroy();
      resolve({ valid: false, error: 'Timeout' });
    });

    req.on('error', (error) => {
      console.log(`❌ API endpoint: ERROR - ${error.message}`);
      resolve({ valid: false, error: error.message });
    });

    req.end();
  });
}

// Main validation function
async function validateCredentials() {
  console.log('🔒 Credential Validation Script');
  console.log('=' .repeat(50));

  try {
    const envVars = parseEnvFile('.env.test');
    const results = {};

    // Test DATABASE_URL
    if (envVars.DATABASE_URL) {
      results.DATABASE_URL = await testDatabaseConnection(envVars.DATABASE_URL);
