const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const app = express();

// Security middleware
app.use(helmet()); // Sets various security headers

// CORS configuration with origin restrictions
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation and sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Basic XSS prevention
  const sanitize = (obj) => {
    if (typeof obj === 'string') {
      return obj.replace(/<script[^>]*>.*?<\/script>/gi, '')
                .replace(/javascript:/gi, '')
                .replace(/on\w+=/gi, '');
    }
    return obj;
  };

  if (req.body) {
    Object.keys(req.body).forEach(key => {
      req.body[key] = sanitize(req.body[key]);
    });
  }

  if (req.query) {
    Object.keys(req.query).forEach(key => {
      req.query[key] = sanitize(req.query[key]);
    });
  }

  next();
};

app.use(sanitizeInput);

// Centralized error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose error details in production
  const errorResponse = process.env.NODE_ENV === 'production'
    ? { error: 'Something went wrong' }
    : { error: err.message, stack: err.stack };

  res.status(err.status || 500).json(errorResponse);
};

// Health endpoint with improved security
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation and data sanitization
app.get('/users', (req, res, next) => {
  try {
    // Input validation
    const { limit, offset } = req.query;

    if (limit && (isNaN(limit) || limit < 1 || limit > 100)) {
      return res.status(400).json({ 
        error: 'Limit must be a number between 1 and 100' 
      });
    }

    if (offset && (isNaN(offset) || offset < 0)) {
      return res.status(400).json({ 
        error: 'Offset must be a non-negative number' 
      });
    }

    // Mock data - in production, this would come from a secure database
    const users = [
      { id: 1, name: 'Alice', email: 'user1@example.com' }, // Obfuscated email
      { id: 2, name: 'Bob', email: 'user2@example.com' }    // Obfuscated email
    ];

    // Apply pagination if provided
    const result = {
      users: users.slice(offset || 0, (offset || 0) + (limit || users.length)),
      total: users.length,
      limit: parseInt(limit) || users.length,
      offset: parseInt(offset) || 0
    };

    res.json(result);
  } catch (error) {
    next(error);
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Apply error handling middleware
app.use(errorHandler);

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

