// Enhanced Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Security Middleware Setup
app.use(helmet()); // Sets various security headers
app.use(cors({ origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000' }));
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Input validation middleware
const validateUserInput = (req, res, next) => {
  // Add specific validation logic for your endpoints
  if (req.body && Object.keys(req.body).length > 20) {
    return res.status(400).json({ 
      error: 'Payload too large', 
      message: 'Request body contains too many fields' 
    });
  }
  next();
};
app.use(validateUserInput);

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Health endpoint with improved error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
    });
  } catch (error) {
    console.error('Health endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to process health check' 
    });
  }
});

// Users endpoint with parameter validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if any
    const { page, limit } = req.query;

    if (page && isNaN(parseInt(page))) {
      return res.status(400).json({ 
        error: 'Invalid parameter', 
        message: 'Page must be a number' 
      });
    }

    if (limit && isNaN(parseInt(limit))) {
      return res.status(400).json({ 
        error: 'Invalid parameter', 
        message: 'Limit must be a number' 
      });
    }

    // Sample user data
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date().toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date().toISOString()
      },
    ];

    res.json({
      data: users,
      metadata: {
        total: users.length,
        page: parseInt(page) || 1,
        limit: parseInt(limit) || 10
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to fetch users' 
    });
  }
});

// Sample POST endpoint with comprehensive input validation
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || typeof name !== 'string' || name.trim().length < 2) {
      return res.status(400).json({ 
        error: 'Invalid input', 
        message: 'Name must be at least 2 characters long' 
      });
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !emailRegex.test(email)) {
      return res.status(400).json({ 
        error: 'Invalid input', 
        message: 'Invalid email format' 
      });
    }

    // Sanitize inputs
    const sanitizedName = name.trim().substring(0, 100);
    const sanitizedEmail = email.trim().toLowerCase().substring(0, 255);

    // Process the data (in a real app, this would save to database)
    const newUser = {
      id: Date.now(),
      name: sanitizedName,
      email: sanitizedEmail,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      data: newUser,
      message: 'User created successfully'
    });

  } catch (error) {
    console.error('Create user endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to create user' 
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found` 
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details in production
  const errorResponse = process.env.NODE_ENV === 'production' 
    ? { error: 'Internal server error' }
    : { error: error.message, stack: error.stack };

  res.status(500).json(errorResponse);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

// Start server with error handling
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
}).on('error', (error) => {
  console.error('Failed to start server:', error);
  process.exit(1);
});

module.exports = app;

