// Enhanced Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const compression = require('compression');
const expressValidator = require('express-validator');

const app = express();

// Security middleware - Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  crossOriginEmbedderPolicy: false,
}));

// Enable CORS with proper configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || []
    : ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Request parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Compression
app.use(compression());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Input validation middleware
app.use(expressValidator());

// Validate environment variables on startup
const validateEnvVars = () => {
  const requiredVars = [];
  const missingVars = requiredVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
  }

  // Check for canary values in production
  if (process.env.NODE_ENV === 'production') {
    const canaryCheckVars = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY'];
    const canaryVars = canaryCheckVars.filter(varName => 
      process.env[varName] && process.env[varName].includes('CANARY')
    );

    if (canaryVars.length > 0) {
      console.warn('WARNING: Canary values detected in production environment:', canaryVars);
      // In production, you might want to throw an error instead
      // throw new Error('Canary values detected in production environment');
    }
  }
};

// Request validation and sanitization middleware
const validateUserRequest = (req, res, next) => {
  req.checkParams('id', 'Invalid user ID').optional().isInt({ min: 1 });
  req.checkQuery('page', 'Invalid page number').optional().isInt({ min: 1 });
  req.checkQuery('limit', 'Invalid limit').optional().isInt({ min: 1, max: 100 });

  const errors = req.validationErrors();
  if (errors) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.map(err => ({ field: err.param, message: err.msg }))
    });
  }

  next();
};

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with proper validation and error handling
app.get('/users', validateUserRequest, (req, res) => {
  try {
    // Simulate pagination with validation
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    if (page < 1 || limit < 1 || limit > 100) {
      return res.status(400).json({ 
        error: 'Invalid pagination parameters',
        message: 'Page must be >= 1, limit must be between 1-100'
      });
    }

    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date().toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date().toISOString()
      },
    ];

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details in production
  const errorResponse = process.env.NODE_ENV === 'production'
    ? { error: 'Internal server error' }
    : { error: error.message, stack: error.stack };

  res.status(500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Process termination handlers
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Exit process in production
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Exit process in production
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Initialize server with environment validation
const startServer = async () => {
  try {
    validateEnvVars();

    const PORT = process.env.PORT || 3000;
    const server = app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
      console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    });

    // Graceful shutdown
    const gracefulShutdown = (signal) => {
      console.log(`Received ${signal}, shutting down gracefully...`);
      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });

      // Force close after 10 seconds
      setTimeout(() => {
        console.error('Could not close connections in time, forcefully shutting down');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Export for testing
module.exports = { app, startServer };

// Start server if this file is run directly
if (require.main === module) {
  startServer();
}

// Security test script to validate implemented measures
const { app, startServer } = require('./app_secure');
const request = require('supertest');

// Test security headers
describe('Security Headers', () => {
  it('should include security headers', async () => {
    const response = await request(app).get('/health');

    expect(response.headers['x-content-type-options']).toBe('nosniff');
    expect(response.headers['x-frame-options']).toBe('SAMEORIGIN');
    expect(response.headers['x-xss-protection']).toBe('0');
    expect(response.headers['strict-transport-security']).toBeDefined();
  });
});

// Test rate limiting
describe('Rate Limiting', () => {
  it('should enforce rate limits', async () => {
    // Make multiple requests quickly
    for (let i = 0; i < 105; i++) {
      const response = await request(app).get('/health');
      if (i >= 100) {
        expect(response.status).toBe(429); // Too Many Requests
      }
    }
  });
});

// Test input validation
describe('Input Validation', () => {
  it('should validate user parameters', async () => {
    const response = await request(app)
      .get('/users?page=invalid&limit=200');

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Validation failed');
  });

  it('should accept valid parameters', async () => {
    const response = await request(app)
      .get('/users?page=1&limit=10');

    expect(response.status).toBe(200);
    expect(response.body.data).toBeDefined();
  });
});

// Test error handling
describe('Error Handling', () => {
  it('should handle 404 errors gracefully', async () => {
    const response = await request(app).get('/nonexistent');
    expect(response.status).toBe(404);
    expect(response.body.error).toBe('Endpoint not found');
  });
});

// Test request size limits
describe('Request Size Limits', () => {
  it('should reject large JSON payloads', async () => {
    const largePayload = { data: 'x'.repeat(20000) }; // 20KB+ payload
    const response = await request(app)
      .post('/some-endpoint')
      .send(largePayload)
      .set('Content-Type', 'application/json');

    // This would typically return 413 Payload Too Large
    expect(response.status).toBeGreaterThanOrEqual(400);
  });
});

console.log('Security tests completed. Run with: npm test');

