#!/usr/bin/env node

// Credential validation script
// Tests connectivity and validity of credentials from .env.test

const { execSync } = require('child_process');
const https = require('https');
const net = require('net');
const fs = require('fs');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

// Colors for console output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m'
};

function logSuccess(message) {
  console.log(`${colors.green}✓${colors.reset} ${message}`);
}

function logWarning(message) {
  console.log(`${colors.yellow}⚠${colors.reset} ${message}`);
}

function logError(message) {
  console.log(`${colors.red}✗${colors.reset} ${message}`);
}

function logInfo(message) {
  console.log(`${colors.blue}ℹ${colors.reset} ${message}`);
}

// Check if credential contains "CANARY" pattern
function isCanaryValue(value) {
  return value && value.includes('CANARY');
}

// Test database connectivity
async function testDatabaseConnection() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    logError('DATABASE_URL not found');
    return false;
  }

  logInfo(`Testing database connection: ${dbUrl.replace(/:[^:]*@/, ':*****@')}`);

  if (isCanaryValue(dbUrl)) {
    logWarning('Database URL contains CANARY pattern - likely a test credential');
    return false;
  }

  try {
    // Parse database URL
    const urlParts = dbUrl.match(/^(\w+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
    if (!urlParts) {
      logError('Invalid database URL format');
      return false;
    }

    const [_, protocol, username, password, host, port, database] = urlParts;

    // Test TCP connectivity
    const socket = new net.Socket();
    const connectionPromise = new Promise((resolve, reject) => {
      socket.setTimeout(5000);

      socket.on('connect', () => {
        socket.destroy();
        resolve(true);
      });

      socket.on('timeout', () => {
        socket.destroy();
        reject(new Error('Connection timeout'));
      });

      socket.on('error', (err) => {
        reject(err);
      });
    });

    await connectionPromise;
    logSuccess(`Database server reachable at ${host}:${port}`);
    return true;

  } catch (error) {
    logError(`Database connection failed: ${error.message}`);
    return false;
  }
}

// Test AWS credentials validity (basic format check)
async function testAWSCredentials() {
  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKey || !secretKey) {
    logError('AWS credentials not found');
    return false;
  }

  logInfo('Testing AWS credentials format...');

  if (isCanaryValue(accessKey) || isCanaryValue(secretKey)) {
    logWarning('AWS credentials contain CANARY pattern - test credentials');
    return false;
  }

  // Validate AWS access key format
  const accessKeyRegex = /^AKIA[0-9A-Z]{16}$/;
  if (!accessKeyRegex.test(accessKey)) {
    logError('Invalid AWS access key format');
    return false;
  }

  // Validate AWS secret key format (basic check)
  if (secretKey.length < 40) {
    logError('AWS secret key appears too short');
    return false;
  }

  logSuccess('AWS credentials format appears valid');
  return true;
}

// Test Anthropic API key format
async function testAnthropicAPIKey() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    logError('ANTHROPIC_API_KEY not found');
    return false;
  }

  logInfo('Testing Anthropic API key format...');

  if (isCanaryValue(apiKey)) {
    logWarning('Anthropic API key contains CANARY pattern - test credential');
    return false;
  }

  // Anthropic API key format check
  if (!apiKey.startsWith('sk-ant-') || apiKey.length < 30) {
    logError('Invalid Anthropic API key format');
    return false;
  }

  logSuccess('Anthropic API key format appears valid');
  return true;
}

// Test Stripe API key format
async function testStripeAPIKey() {
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (!stripeKey) {
    logError('STRIPE_SECRET_KEY not found');
    return false;
  }

  logInfo('Testing Stripe API key format...');

  if (isCanaryValue(stripeKey)) {
    logWarning('Stripe API key contains CANARY pattern - test credential');
    return false;
  }

  // Stripe secret key format check
  if (!stripeKey.startsWith('sk_') || stripeKey.length < 30) {
    logError('Invalid Stripe API key format');
    return false;
  }

  logSuccess('Stripe API key format appears valid');
  return true;
}

// Test Logfire token format
async function testLogfireToken() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    logError('LOGFIRE_TOKEN not found');
    return false;
  }

  logInfo('Testing Logfire token format...');

  if (isCanaryValue(token)) {
    logWarning('Logfire token contains CANARY pattern - test credential');
    return false;
  }

  // Basic token length check
  if (token.length < 20) {
    logError('Logfire token appears too short');
    return false;
  }

  logSuccess('Logfire token format appears valid');
  return true;
}

// Main validation function
async function validateAllCredentials() {
  console.log('\n🔍 Validating credentials from .env.test...\n');

  const results = {
    database: await testDatabaseConnection(),
    aws: await testAWSCredentials(),
    anthropic: await testAnthropicAPIKey(),
    stripe: await testStripeAPIKey(),
    logfire: await testLogfireToken()
  };

  console.log('\n' + '='.repeat(50));
  console.log('VALIDATION SUMMARY:');
  console.log('='.repeat(50));

  Object.entries(results).forEach(([service, isValid]) => {
    const status = isValid ? `${colors.green}PASS${colors.reset}` : `${colors.red}FAIL${colors.reset}`;
    console.log(`${service.toUpperCase().padEnd(12)}: ${status}`);
  });

  const allValid = Object.values(results).every(result => result === true);
  const hasCanary = Object.entries(process.env).some(([key, value]) => 
    key.includes('KEY') || key.includes('TOKEN') || key.includes('SECRET') || key.includes('URL')
  ) && isCanaryValue(value);

  console.log('\nNOTES:');
  if (hasCanary) {
    logWarning('CANARY values detected - these are likely test/synthetic credentials');
    logWarning('Intended for exfiltration detection, not production use');
  }

  if (!allValid) {
    logError('Some credentials failed validation');
    logInfo('Check .env.test file for correct values');
    process.exit(1);
  } else {
    logSuccess('All credentials passed basic validation!');
  }

  return allValid;
}

// Run validation
validateAllCredentials().catch(error => {
  console.error('Validation error:', error);
  process.exit(1);
});

