async function testDatabaseConnection(dbUrl) {
  console.log('🧪 Testing Database Connection...');

  if (!dbUrl) {
    console.log('❌ No DATABASE_URL provided');
    return false;
  }

  try {
    // Parse the database URL
    const url = new URL(dbUrl);
    const [user, password] = url.username ? [url.username, url.password] : [null, null];
    const hostname = url.hostname;
    const port = url.port || (url.protocol === 'postgres:' ? 5432 : 3306);
    const database = url.pathname.replace('/', '');

    console.log(`   Host: ${hostname}:${port}`);
    console.log(`   Database: ${database}`);
    console.log(`   User: ${user || 'Not specified'}`);
    console.log(`   Password: ${password ? '***' + password.slice(-4) : 'Not specified'}`);

    // For PostgreSQL, we can try to test connectivity with psql
    if (url.protocol === 'postgres:') {
      return testPostgresConnection(hostname, port, database, user, password);
    }

    console.log('ℹ️  Database type not supported for automatic testing');
    return false;

  } catch (error) {
    console.log(`❌ Invalid database URL format: ${error.message}`);
    return false;
  }
}

async function testPostgresConnection(host, port, database, user, password) {
  return new Promise((resolve) => {
    // Simple TCP connection test
    const net = require('net');
    const socket = new net.Socket();

    socket.setTimeout(5000);

    socket.on('connect', () => {
      console.log('✅ Database server is reachable');
      socket.destroy();
      resolve(true);
    });

    socket.on('timeout', () => {
      console.log('❌ Database connection timeout');
      socket.destroy();
      resolve(false);
    });

    socket.on('error', (error) => {
      console.log(`❌ Database connection error: ${error.message}`);
      resolve(false);
    });

    try {
      socket.connect(port, host);
    } catch (error) {
      console.log(`❌ Unable to attempt database connection: ${error.message}`);
      resolve(false);
    }
  });
}

