// Function to safely remove or secure environment files
function cleanupEnvironment() {
  const envFiles = [
    '.env.test',
    '.env',
    '.env.local',
    '.env.development',
    '.env.production'
  ];

  let actionsTaken = [];

  envFiles.forEach(file => {
    if (fs.existsSync(file)) {
      try {
        const content = fs.readFileSync(file, 'utf8');

        // Check if file contains canary values
        const hasCanary = content.includes('CANARY');

        if (hasCanary) {
          // For security, let's not automatically delete files
          // Instead, we'll create a backup and notify
          const backupFile = `${file}.backup-${Date.now()}`;
          fs.copyFileSync(file, backupFile);

          actionsTaken.push({
            file,
            action: 'BACKED_UP',
            reason: 'Contains canary values - backup created',
            backup: backupFile
          });
        } else {
          actionsTaken.push({
            file,
            action: 'PRESENT',
            reason: 'No canary values detected'
          });
        }

      } catch (error) {
        actionsTaken.push({
          file,
          action: 'ERROR',
          reason: `Could not read file: ${error.message}`
        });
      }
    } else {
      actionsTaken.push({
        file,
        action: 'NOT_FOUND',
        reason: 'File does not exist'
      });
    }
  });

  return actionsTaken;
}

// Function to create secure environment template
function createSecureTemplate() {
  const template = `# Secure Environment Configuration
# Replace with your actual development values

NODE_ENV=development
PORT=3000

# Database - use local development database
DATABASE_URL=postgres://username:password@localhost:5432/development_db

# API Keys - obtain from your development accounts
# AWS_ACCESS_KEY_ID=your_development_aws_key
# AWS_SECRET_ACCESS_KEY=your_development_aws_secret
# STRIPE_SECRET_KEY=REDACTED_STRIPE_TEST
# ANTHROPIC_API_KEY=your_development_anthropic_key
# LOGFIRE_TOKEN=your_development_logfire_token

# Security
JWT_SECRET=your_secure_random_jwt_secret_32+_chars
`;

  const templatePath = '.env.secure-template';

  if (!fs.existsSync(templatePath)) {
    fs.writeFileSync(templatePath, template);
    return templatePath;
  }

  return null;
}

// Main cleanup process
function performCleanup() {
  console.log('📋 Scanning environment files...\n');

  const actions = cleanupEnvironment();
  const templateCreated = createSecureTemplate();

  console.log('📊 Cleanup Results:');
  console.log('='.repeat(60));

  actions.forEach(({ file, action, reason, backup }) => {
    let status = '';
    switch (action) {
      case 'BACKED_UP':
        status = '⚠️  BACKED UP';
        break;
      case 'PRESENT':
        status = '✅ PRESENT';
        break;
      case 'NOT_FOUND':
        status = 'ℹ️  NOT FOUND';
        break;
      case 'ERROR':
        status = '❌ ERROR';
        break;
    }

    console.log(`${file.padEnd(20)}: ${status} - ${reason}`);
    if (backup) {
      console.log(`                       Backup: ${backup}`);
    }
  });

  console.log('='.repeat(60));

  if (templateCreated) {
    console.log(`\n📝 Created secure environment template: ${templateCreated}`);
    console.log('   Use this as a starting point for your development environment.');
  }

  // Security recommendations
  console.log('\n🔒 Security Recommendations:');
  console.log('1. Review all backed up files for canary values');
  console.log('2. Remove canary values from production environments');
  console.log('3. Use the secure template to create your .env file');
  console.log('4. Never commit actual credentials to version control');
  console.log('5. Use environment-specific credential management');

  const hasCanaryFiles = actions.some(a => a.action === 'BACKED_UP');

  if (hasCanaryFiles) {
    console.log('\n⚠️  WARNING: Canary values detected in environment files!');
    console.log('   These should be removed from any production environments.');
  }
}

// Run the cleanup
performCleanup();

