function readCredentials() {
  try {
    const envContent = fs.readFileSync('.env.test', 'utf8');
    const credentials = {};

    envContent.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        const value = valueParts.join('=').trim();
        if (key && value) {
          credentials[key.trim()] = value;
        }
      }
    });

    return credentials;
  } catch (error) {
    console.log('❌ Could not read .env.test file:', error.message);
    return {};
  }
}

const credentials = readCredentials();

// Test Stripe API key
function testStripeApi() {
  return new Promise((resolve) => {
    if (!credentials.STRIPE_SECRET_KEY) {
      resolve({ valid: false, error: 'No Stripe key provided' });
      return;
    }

    const options = {
      hostname: 'api.stripe.com',
      port: 443,
      path: '/v1/balance',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${credentials.STRIPE_SECRET_KEY}`,
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      timeout: 10000
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200) {
          resolve({ valid: true, message: 'Stripe API key is valid' });
        } else if (res.statusCode === 401) {
          resolve({ valid: false, error: 'Stripe API key is invalid (401 Unauthorized)' });
        } else {
          resolve({ valid: false, error: `Stripe API returned status ${res.statusCode}` });
        }
      });
    });

    req.on('error', (error) => {
      resolve({ valid: false, error: `Stripe API error: ${error.message}` });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ valid: false, error: 'Stripe API request timeout' });
    });

    req.end();
  });
}

// Test Anthropic API key
function testAnthropicApi() {
  return new Promise((resolve) => {
    if (!credentials.ANTHROPIC_API_KEY) {
      resolve({ valid: false, error: 'No Anthropic key provided' });
      return;
    }

    const postData = JSON.stringify({
      model: 'claude-3-sonnet-20240229',
      max_tokens: 5,
      messages: [{ role: 'user', content: 'Hello' }]
    });

    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
      method: 'POST',
      headers: {
        'x-api-key': credentials.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'Content-Type': 'application/json',
        'Content-Length': postData.length
      },
      timeout: 10000
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 400) {
          // 400 might indicate invalid request but valid auth
          resolve({ valid: true, message: 'Anthropic API key appears valid' });
        } else if (res.statusCode === 401 || res.statusCode === 403) {
          resolve({ valid: false, error: 'Anthropic API key is invalid' });
        } else {
          resolve({ valid: false, error: `Anthropic API returned status ${res.statusCode}` });
        }
      });
    });

    req.on('error', (error) => {
      resolve({ valid: false, error: `Anthropic API error: ${error.message}` });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ valid: false, error: 'Anthropic API request timeout' });
    });

