// Credential verification script
// Tests connectivity and validity of credentials from .env.test

const https = require('https');
const { Client } = require('pg');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

async function testDatabaseConnection() {
  console.log('Testing database connection...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  const client = new Client({
    connectionString: process.env.DATABASE_URL,
    connectionTimeoutMillis: 5000,
    ssl: { rejectUnauthorized: false }
  });

  try {
    await client.connect();
    console.log('✅ Successfully connected to database');

    // Test a simple query
    const result = await client.query('SELECT NOW() as current_time');
    console.log(`✅ Database query successful: ${result.rows[0].current_time}`);

    await client.end();
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

async function testAPIKeyValidity(keyName, validationUrl, validationMethod = 'GET') {
  console.log(`\nTesting ${keyName}...`);

  const apiKey = process.env[keyName];
  if (!apiKey) {
    console.log(`❌ ${keyName} not found in environment`);
    return false;
  }

  console.log(`📋 ${keyName}: ${apiKey.substring(0, 10)}...${apiKey.substring(apiKey.length - 4)}`);

  // Check if it's a canary value
  if (apiKey.includes('CANARY')) {
    console.log('⚠️  Detected CANARY value - synthetic test credential');
    return 'canary';
  }

  if (!validationUrl) {
    console.log('ℹ️  No validation URL provided for this API key type');
    return 'no_validation';
  }

  return new Promise((resolve) => {
    const req = https.request(validationUrl, {
      method: validationMethod,
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json'
      },
      timeout: 5000
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 201) {
          console.log(`✅ ${keyName} appears to be valid (HTTP ${res.statusCode})`);
          resolve(true);
        } else {
          console.log(`❌ ${keyName} validation failed (HTTP ${res.statusCode})`);
          console.log(`Response: ${data.substring(0, 200)}...`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${keyName} validation error:`, error.message);
      resolve(false);
    });

    req.on('timeout', () => {
      console.log(`❌ ${keyName} validation timeout`);
      req.destroy();
      resolve(false);
    });

    req.end();
  });
}

async function main() {
  console.log('🔍 Verifying credentials from .env.test\n');

  // Test database connection
  const dbResult = await testDatabaseConnection();

  // Test AWS credentials (using AWS STS GetCallerIdentity as validation)
  const awsResult = await testAPIKeyValidity(
    'AWS_ACCESS_KEY_ID',
    null // AWS validation requires AWS SDK which we don't want to install
  );

  // Test Anthropic API key
  const anthropicResult = await testAPIKeyValidity(
    'ANTHROPIC_API_KEY',
    'https://api.anthropic.com/v1/messages',
    'POST'
  );

  // Test Stripe API key
  const stripeResult = await testAPIKeyValidity(
    'STRIPE_SECRET_KEY',
    'https://api.stripe.com/v1/balance',
    'GET'
  );

  // Test Logfire token
  const logfireResult = await testAPIKeyValidity(
    'LOGFIRE_TOKEN',
    null // Logfire validation endpoint unknown
  );

  console.log('\n📊 Summary of Results:');
  console.log(`Database: ${dbResult ? '✅ Valid' : '❌ Invalid'}`);
  console.log(`AWS Keys: ${awsResult === 'canary' ? '⚠️  Canary' : awsResult ? '✅ Valid' : '❌ Invalid'}`);
  console.log(`Anthropic: ${anthropicResult === 'canary' ? '⚠️  Canary' : anthropicResult ? '✅ Valid' : '❌ Invalid'}`);
  console.log(`Stripe: ${stripeResult === 'canary' ? '⚠️  Canary' : stripeResult ? '✅ Valid' : '❌ Invalid'}`);
