// Environment-based configuration
const isProduction = process.env.NODE_ENV === 'production';
const port = process.env.PORT || 3000;

// Security middleware
app.use(helmet());
app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? 'https://yourdomain.com' : true,
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateRequest = (req, res, next) => {
  // Check for common injection patterns
  const injectionPatterns = ['<script>', 'javascript:', 'eval(', 'exec(', '--', ';', '/*', '*/'];
  const queryString = JSON.stringify(req.query);

  if (injectionPatterns.some(pattern => queryString.includes(pattern))) {
    return res.status(400).json({ 
      error: 'Invalid input detected',
      message: 'Request contains potentially malicious content'
    });
  }

  next();
};

app.use(validateRequest);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  try {
    // Validate query parameters if they exist
    const { limit, offset } = req.query;

    if (limit && (!Number.isInteger(Number(limit)) || Number(limit) > 100)) {
      return res.status(400).json({
        error: 'Invalid parameter',
        message: 'Limit must be an integer not exceeding 100'
      });
    }

    if (offset && (!Number.isInteger(Number(offset)) || Number(offset) < 0)) {
      return res.status(400).json({
        error: 'Invalid parameter', 
        message: 'Offset must be a non-negative integer'
      });
    }

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
