// Secure Express.js application with enhanced error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { validationResult, query } = require('express-validator');
require('dotenv').config(); // Load environment variables

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  frameguard: { action: 'deny' },
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true,
}));

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({
      error: 'Internal Server Error',
      message: 'Something went wrong',
      requestId: req.id || 'unknown'
    });
  }

  res.status(500).json({
    error: err.name || 'Error',
    message: err.message,
    stack: err.stack,
    requestId: req.id || 'unknown'
  });
});

// Health endpoint with input validation
app.get('/health', [
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
], (req, res) => {
  // Validate input
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation Error',
      details: errors.array()
    });
  }

  try {
    const detailed = req.query.detailed === 'true';
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    };

    if (detailed) {
      response.memoryUsage = process.memoryUsage();
      response.nodeVersion = process.version;
    }

    res.json(response);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Health check failed',
      message: 'Unable to complete health check'
    });
  }
});

// Users endpoint with proper validation and error handling
app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('offset must be a positive integer')
], async (req, res) => {
  try {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation Error',
        details: errors.array()
      });
    }

    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;

    // Simulate database call with error handling
    const users = await getUsersFromDatabase(limit, offset);

    res.json({
      users,
      pagination: {
        limit,
        offset,
        total: users.length,
        hasMore: users.length === limit
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);

    if (error.name === 'DatabaseError') {
      return res.status(503).json({
        error: 'Service Unavailable',
        message: 'Database temporarily unavailable'
      });
    }

    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Failed to retrieve users'
    });
  }
});

// Simulated database function with error handling
async function getUsersFromDatabase(limit, offset) {
  // This would be your actual database call
  // For demonstration, we'll simulate some data and potential errors

  if (Math.random() < 0.1) { // 10% chance of simulated DB error
    const error = new Error('Database connection timeout');
    error.name = 'DatabaseError';
    throw error;
  }

  return [
    { 
      id: 1 + offset, 
      name: 'Alice', 
      email: 'alice@example.com',
      createdAt: new Date().toISOString()
    },
    { 
      id: 2 + offset, 
      name: 'Bob', 
      email: 'bob@example.com',
      createdAt: new Date().toISOString()
    }
  ].slice(0, limit);
}

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`,
    suggest: 'Check the API documentation for available endpoints'
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
