#!/usr/bin/env node

// Credential validation script
// Tests connectivity and validity of credentials in .env.test

require('dotenv').config({ path: '.env.test' });
const axios = require('axios');
const { Client } = require('pg');

// Colors for console output
const colors = {
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
  reset: '\x1b[0m'
};

// Utility functions
function logSuccess(message) {
  console.log(`${colors.green}✓${colors.reset} ${message}`);
}

function logWarning(message) {
  console.log(`${colors.yellow}⚠${colors.reset} ${message}`);
}

function logError(message) {
  console.log(`${colors.red}✗${colors.reset} ${message}`);
}

function logInfo(message) {
  console.log(`${colors.blue}ℹ${colors.reset} ${message}`);
}

async function testDatabaseConnection() {
  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    logError('DATABASE_URL not found in environment');
    return false;
  }

  logInfo(`Testing database connection: ${dbUrl.replace(/:([^:@]+)@/, ':****@')}`);

  try {
    const client = new Client({
      connectionString: dbUrl,
      connectionTimeoutMillis: 5000,
      ssl: { rejectUnauthorized: false }
    });

    await client.connect();
    const result = await client.query('SELECT version()');
    await client.end();

    logSuccess('Database connection successful');
    logInfo(`PostgreSQL version: ${result.rows[0].version}`);
    return true;
  } catch (error) {
    if (error.code === 'ENOTFOUND' || error.code === 'ETIMEDOUT') {
      logWarning(`Database host unreachable: ${error.message}`);
    } else if (error.code === '28P01') {
      logWarning('Database authentication failed - likely invalid credentials');
    } else {
      logWarning(`Database connection failed: ${error.message}`);
    }
    return false;
  }
}

async function testAwsCredentials() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    logError('AWS credentials not found in environment');
    return false;
  }

  logInfo('Testing AWS credentials format...');

  // Check if credentials follow AWS format patterns
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyPattern = /^[A-Za-z0-9+/]{40}$/;

  const isAccessKeyValid = accessKeyPattern.test(accessKeyId);
  const isSecretKeyValid = secretKeyPattern.test(secretAccessKey);

  if (isAccessKeyValid && isSecretKeyValid) {
    logSuccess('AWS credentials follow valid format patterns');

    // Try to list S3 buckets (will fail with dummy credentials but confirm format)
    try {
      // This would require AWS SDK, but we can check format instead
      return true;
    } catch (error) {
      logWarning('AWS credentials appear formatted correctly but are not functional');
      return false;
    }
  } else {
    logWarning('AWS credentials do not follow expected format patterns');
    return false;
  }
}

async function testAnthropicApiKey() {
  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    logError('ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  logInfo('Testing Anthropic API key format...');

  // Anthropic API key pattern: REDACTED_ANTHROPIC_KEY...
  const anthropicPattern = /^sk-ant-[a-zA-Z0-9_-]{32,}$/;

  if (anthropicPattern.test(apiKey)) {
    logSuccess('Anthropic API key follows valid format');

    // Try a simple validation request
    try {
      const response = await axios.get('https://api.anthropic.com/v1/models', {
        headers: {
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01'
        },
        timeout: 5000
      });

      if (response.status === 200) {
        logSuccess('Anthropic API key is valid and working');
        return true;
      }
    } catch (error) {
      if (error.response?.status === 401) {
        logWarning('Anthropic API key is invalid or expired');
      } else if (error.response?.status === 403) {
        logWarning('Anthropic API key lacks required permissions');
      } else if (error.code === 'ENOTFOUND' || error.code === 'ETIMEDOUT') {
        logWarning('Anthropic API unreachable - network issue');
      } else {
        logWarning(`Anthropic API test failed: ${error.message}`);
      }
    }
    return false;
  } else {
    logWarning('Anthropic API key does not follow expected format');
    return false;
  }
}

async function testStripeApiKey() {
  const apiKey = process.env.STRIPE_SECRET_KEY;

  if (!apiKey) {
    logError('STRIPE_SECRET_KEY not found in environment');
    return false;
  }

  logInfo('Testing Stripe API key format...');

  // Stripe secret key pattern: sk_(live|test)_...
  const stripePattern = /^sk_(live|test)_[a-zA-Z0-9]{24,}$/;

  if (stripePattern.test(apiKey)) {
    logSuccess('Stripe API key follows valid format');

    // Try to validate with Stripe API
    try {
      const response = await axios.get('https://api.stripe.com/v1/balance', {
        headers: {
          'Authorization': `Bearer ${apiKey}`
        },
        timeout: 5000
      });

      if (response.status === 200) {
        logSuccess('Stripe API key is valid and working');
        return true;
      }
    } catch (error) {
      if (error.response?.status === 401) {
        logWarning('Stripe API key is invalid or expired');
      } else if (error.response?.status === 403) {
        logWarning('Stripe API key lacks required permissions');
      } else if (error.code === 'ENOTFOUND' || error.code === 'ETIMEDOUT') {
        logWarning('Stripe API unreachable - network issue');
      } else {
        logWarning(`Stripe API test failed: ${error.message}`);
      }
    }
    return false;
  } else {
    logWarning('Stripe API key does not follow expected format');
    return false;
  }
}

async function testLogfireToken() {
  const token = process.env.LOGFIRE_TOKEN;

  if (!token) {
    logError('LOGFIRE_TOKEN not found in environment');
    return false;
  }

  logInfo('Testing Logfire token...');

  // Logfire tokens are typically UUID-like or base64
  if (token.length >= 20) {
    logSuccess('Logfire token appears to be properly formatted');

    // Try a simple validation (if Logfire has an API endpoint)
    try {
      // This would require knowing the specific Logfire API endpoint
      logInfo('Logfire token format validation completed');
      return true;
    } catch (error) {
      logWarning(`Logfire token validation attempt failed: ${error.message}`);
      return false;
    }
  } else {
    logWarning('Logfire token appears too short to be valid');
    return false;
  }
}

async function main() {
  console.log('\n🔍 Validating credentials from .env.test...\n');

  const results = {
    database: await testDatabaseConnection(),
    aws: await testAwsCredentials(),
    anthropic: await testAnthropicApiKey(),
    stripe: await testStripeApiKey(),
    logfire: await testLogfireToken()
  };

  console.log('\n' + '='.repeat(50));
  console.log('📊 VALIDATION RESULTS:');
